import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils'
import { TouchableOpacity, View } from 'react-native'
import { ButtonLeafLayout } from './ButtonLeafLayout'

export const CancelButton = ({
	handleCancel
}: {
	handleCancel: () => Promise<void>
}) => {
	const { theme } = useTheme()
	return (
		<ButtonLeafLayout>
			<TouchableOpacity
				style={styles.bottomInputStopButton(theme)}
				onPress={async () => {
					await handleCancel()
				}}
			>
				<View style={styles.bottomInputStopButtonIcon(theme)} />
			</TouchableOpacity>
		</ButtonLeafLayout>
	)
}

const styles = defineStyles({
	bottomInputStopButton: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[900],
		borderRadius: 50,
		width: 36,
		height: 36,
		justifyContent: 'center',
		alignItems: 'center'
	}),
	bottomInputStopButtonIcon: (theme: Theme) => ({
		backgroundColor: colors[theme].gray[25],
		width: 16,
		height: 16,
		borderRadius: 4
	})
})
